<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api,session,money,date,notify,type Row} from '../api';import Icon from '../components/Icon.vue';import Modal from '../components/Modal.vue'
const route=useRoute(),kind=route.path.slice(1),rows=ref<Row[]>([]),customers=ref<Row[]>([]),query=ref(''),show=ref(false),busy=ref(false),error=ref(''),pageError=ref(''),editId=ref<number|null>(null),form=ref<Row>({}),mode=ref('record')
const titles:Record<string,string>={customers:'Clientes',vehicles:'Vehículos',employees:'Equipo del taller',inventory:'Inventario',audit:'Auditoría'}
const descriptions:Record<string,string>={customers:'Personas que confían en tu taller.',vehicles:'La información de cada vehículo, siempre a mano.',employees:'Las personas detrás de cada buen servicio.',inventory:'Cada pieza cuenta. Mantén tus existencias en orden.',audit:'Una bitácora de las operaciones importantes.'}
const columns:Record<string,[string,string][]>= {customers:[['full_name','Cliente'],['phone','Teléfono'],['email','Correo']],vehicles:[['make','Marca'],['model','Modelo'],['model_year','Año'],['license_plate','Matrícula'],['customer_name','Propietario']],employees:[['full_name','Nombre'],['email','Correo'],['role_code','Rol'],['enabled','Acceso']],inventory:[['sku','Código'],['name','Pieza'],['stock','Existencias'],['minimum_stock','Mínimo'],['reference_price','Precio']],audit:[['created_at','Fecha'],['action','Acción'],['entity_type','Registro'],['actor','Responsable']]}
const fields=computed(()=>mode.value==='movement'?[['partId','Pieza','part'],['kind','Movimiento','movement'],['quantity','Cantidad','number'],['cost','Costo unitario de entrada','number'],['reason','Motivo','text']]:kind==='customers'?[['name','Nombre completo','text'],['phone','Teléfono','tel']]:kind==='vehicles'?[...(session.user?.role==='ADMIN'?[['customerId','Cliente','customer']]:[]),['make','Marca','text'],['model','Modelo','text'],['year','Año','number'],['plate','Matrícula','text'],['vin','VIN (opcional)','text']]:kind==='employees'?[['name','Nombre completo','text'],['email','Correo electrónico','email'],['role','Rol','role'],['password','Contraseña inicial (12 caracteres)','password']]:[['sku','Código de pieza','text'],['name','Nombre de la pieza','text'],['unit','Unidad','unit'],['minimum','Stock mínimo','number'],['price','Precio de venta','number']])
const filtered=computed(()=>rows.value.filter(r=>JSON.stringify(r).toLowerCase().includes(query.value.toLowerCase())))
const endpoint=kind==='inventory'?'parts':kind
async function load(){try{rows.value=await api('/'+endpoint)}catch(e:any){pageError.value=e.message}}
async function open(row?:Row,movement=false){editId.value=row?.id||null;mode.value=movement?'movement':'record';error.value='';form.value=movement?{partId:row?.id||'',kind:'RECEIPT',quantity:1,cost:0,reason:'',requestKey:crypto.randomUUID()}:{name:row?.full_name||row?.name||'',phone:row?.phone||'',sku:row?.sku||'',unit:row?.unit||'UNIT',minimum:row?.minimum_stock||0,price:row?.reference_price||0,role:'MECHANIC',year:2020,...(kind==='vehicles'?{customerId:'',make:'',model:'',plate:'',vin:''}:{})};if(kind==='vehicles'&&session.user?.role==='ADMIN')customers.value=await api('/customers');show.value=true}
async function save(){busy.value=true;error.value='';try{await api(mode.value==='movement'?'/inventory/movements':'/'+endpoint+(editId.value?'/'+editId.value:''),mode.value==='movement'||!editId.value?'POST':'PUT',form.value);show.value=false;notify('Cambios guardados');await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function access(r:Row){try{await api('/employees/'+r.user_id+'/access','PUT',{enabled:!r.enabled});await load();notify('Acceso actualizado')}catch(e:any){notify(e.message,'error')}}
onMounted(load)
</script>
<template><div class="page-heading"><div><p class="eyebrow">TU TALLER, ORGANIZADO</p><h1>{{titles[kind]}}</h1><p class="muted">{{descriptions[kind]}}</p></div><div class="button-row"><button v-if="kind==='inventory'&&session.user?.role==='ADMIN'" class="btn secondary" @click="open(undefined,true)"><Icon name="box"/>Registrar movimiento</button><button v-if="kind!=='audit'&&(session.user?.role==='ADMIN'||kind==='vehicles'&&session.user?.role==='CLIENT')" class="btn primary" @click="open()"><Icon name="plus"/>{{kind==='inventory'?'Nueva pieza':kind==='vehicles'?'Nuevo vehículo':kind==='employees'?'Agregar integrante':'Nuevo cliente'}}</button></div></div><div v-if="kind==='inventory'" class="inventory-note"><Icon name="box"/><span><strong>{{rows.filter(r=>Number(r.stock)<=Number(r.minimum_stock)).length}} piezas necesitan atención.</strong> Las existencias cambian al registrar movimientos o usar piezas en una orden.</span></div><section class="panel"><div class="table-toolbar"><div class="search"><Icon name="search"/><input v-model="query" :placeholder="'Buscar en '+titles[kind].toLowerCase()+'…'" aria-label="Buscar registros"></div><span class="muted small">{{rows.length}} registros</span></div><p v-if="pageError" class="error">{{pageError}}</p><div class="table-wrap"><table><thead><tr><th v-for="[,label] in columns[kind]">{{label}}</th><th v-if="kind!=='audit'"></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td v-for="([key],i) in columns[kind]" :class="{'table-primary':i===0,'stock-low':key==='stock'&&Number(r.stock)<=Number(r.minimum_stock)}">{{key==='reference_price'?money(r[key]):key==='created_at'?date(r[key]):key==='enabled'?(r[key]?'Activo':'Suspendido'):key==='role_code'?(r[key]==='ADMIN'?'Administrador':'Mecánico'):r[key]||'—'}}</td><td v-if="kind!=='audit'"><button v-if="['customers','inventory'].includes(kind)&&session.user?.role==='ADMIN'" class="text-link" @click="open(r)">Editar</button><button v-if="kind==='employees'" class="text-link" @click="access(r)">{{r.enabled?'Suspender':'Activar'}}</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty"><Icon :name="kind==='inventory'?'box':'users'" :size="36"/><h3>Sin registros todavía</h3><p>Los registros aparecerán aquí conforme trabajes.</p></div></div></section><Modal v-if="show" :title="mode==='movement'?'Movimiento de inventario':(editId?'Editar registro':'Agregar registro')" :busy="busy" :error="error" @close="show=false" @submit="save"><label v-for="[key,label,type] in fields">{{label}}<select v-if="['customer','part','role','unit','movement'].includes(type)" v-model="form[key]" required><template v-if="type==='customer'"><option disabled value="">Selecciona un cliente</option><option v-for="c in customers" :value="c.id">{{c.full_name}}</option></template><template v-else-if="type==='part'"><option disabled value="">Selecciona una pieza</option><option v-for="p in rows" :value="p.id">{{p.name}}</option></template><template v-else-if="type==='role'"><option value="MECHANIC">Mecánico</option><option value="ADMIN">Administrador</option></template><template v-else-if="type==='unit'"><option value="UNIT">Pieza</option><option value="L">Litro</option></template><template v-else><option value="RECEIPT">Entrada de compra</option><option value="ADJUSTMENT">Ajuste (cantidad positiva o negativa)</option></template></select><input v-else v-model="form[key]" :type="type" :required="!['vin','phone'].includes(key)" :minlength="type==='password'?12:undefined" :min="type==='number'&&!(mode==='movement'&&key==='quantity')?0:undefined" :step="type==='number'?'any':undefined" :maxlength="key==='vin'?17:160"></label></Modal></template>
